			title = "El visitante",
			hint = "Averigüe quién vino a ver a Bazil Thredd antes del motín.",
			text = [=[El alcaide recordaba a un extraño visitante que había acudido a la celda de Thredd poco antes del levantamiento. Anotó todo lo que pudo recordar y lo selló. Esa descripción sellada viajó desde las {link:the-stockade}Mazmorras{/link} hasta el Arquitecto de la Ciudad, y de él hasta el jefe del {link:si-7}SI:7{/link}. Al final, condujo a un traidor en el castillo de {link:stormwind-city}Ventormenta{/link}.]=],
		},
	},
	mentions = {
		{ text = "La carta sin enviar" },
		{ text = "Bazil Thredd" },
		{ text = "Los disturbios de las {link:the-stockade}Mazmorras{/link}" },
		{ text = "El curioso visitante" },
	},
	bonds = {
		{ id = "edwin-vancleef", name = "Edwin VanCleef", note = "su señor" },
		{ id = "warden-thelwater", name = "Alcaide Thelwater", note = "su carcelero" },
		{ id = "baros-alexston", name = "Baros Alexston", note = "puso en marcha su búsqueda" },
		{ id = "gregor-lescovar", name = "Gregor Lescovar", note = "el traidor al que condujo su visitante" },
	},
})

